    terms: 'NET14',
  });

  const issued = issueInvoice(inv.value, []).value;
  const totals = invoiceTotals(issued);

  // Due 2025-10-21, asOf 2025-11-04 = 14 days overdue
  // fee = 145200 * 14 * 0.04 / 100 = 812.16 cents, rounded to 813
  const fee = lateFee(issued, '2025-11-04');

  // 145200 * 14 * 0.04 / 100 = 812.16 → 813 cents (banker's rounding)
  assert.equal(fee, 813);
});

